use std::future::Future;

trait Cache {
    fn get(&self, key: u32) -> impl Future<Output = Option<String>> + Send;

    fn get_or(&self, key: u32, dflt: String) -> impl Future<Output = String> + Send {
        async move { self.get(key).await.unwrap_or(dflt) }
    }
}

// Implementors do not override `get_or`; callers run it with tokio::spawn.
